    if (isNative) return; // browser's own replaceAll is intact, nothing to do

    function escapeRegExp(s) {
        return s.replace(/[.*+?^${}()|[\]\\\/-]/g, "\\$&");
    }

    function replaceAll(search, replacement) {
        if (this == null) {
            throw new TypeError("String.prototype.replaceAll called on null or undefined");
        }
        var input = String(this);

        if (search instanceof RegExp) {
            if (!search.global) {
                throw new TypeError("replaceAll must be called with a global RegExp");
            }
            return input.replace(search, replacement);
        }
        // Treat the search string literally; $&, $$ and function replacers behave like native
        return input.replace(new RegExp(escapeRegExp(String(search)), "g"), replacement);
    }

    // Keep CivicPlus's regex-style version available under an alias
    if (typeof current === "function") {
        Object.defineProperty(proto, "replaceAllReg", {
            configurable: true, writable: true, value: current
