        enumerable: false,
        get: function () { return replaceAll; },
        set: function (fn) {
            if (typeof fn === "function") {
                Object.defineProperty(proto, "replaceAllReg", {
                    configurable: true, writable: true, value: fn
                });
            }
        }
    });
})();
